// The API documentation's message pane at the narrowest
// width that shows a request beside its response: what a
// line of a sample holds there, and what a block adds to
// its lines. The pane height in the stylesheet is derived
// from these over the committed samples, and the browser
// checks them against the real pane.

// pages-api-documentation.css's side-by-side breakpoint.
export const SIDE_BY_SIDE_WIDTH = 1440;

// The characters one line of a message block holds.
export const PANE_COLUMNS = 60;

// One line of a message block, in pixels.
export const PANE_LINE_PX = 21;

// A block's padding and border, top and bottom together.
export const PANE_CHROME_PX = 34;
